export function validateEconomy(s){if(!s.srEconomy)return true;const e=s.srEconomy;if(e.version!=='economy:yunxiu:v1'||!Number.isSafeInteger(e.nextId)||e.nextId<1||e.updatedThroughTick>s.worldTick)fail('经济版本/游标异常。');if(!e.wholesale||e.wholesale.windowSpent<0||e.wholesale.windowSpent>WHOLESALE_DEFINITION.periodBudget+1e-9||e.wholesale.spentLifetime>WHOLESALE_DEFINITION.lifetimeTreasury+1e-9||!Object.entries(e.resaleInventory).every(([k,v])=>RESOURCES[k]&&Number.isFinite(v)&&v>=-1e-9))fail('批发库存/周期预算异常。');if(e.pillInventoryVersion){if(e.pillInventoryVersion!=='positioned-pills:v1'||!s.factsById['fact:pill-stock-migration:v1'])fail('药物位置迁移标记或事实异常。');for(const st of Object.values(s.stockpilesById))if(st.pills&&(Object.keys(st.pills).length!==Object.keys(RECIPES).length||!Object.entries(st.pills).every(([id,q])=>RECIPES[id]&&Number.isSafeInteger(q)&&q>=0)))fail('实际药库计数异常：'+st.id);for(const[id,a]of Object.entries(e.pillAllocations)){if(a.id!==id||!s.personsById[a.personId]||!RECIPES[a.recipeId]||!Number.isSafeInteger(a.quantity)||a.quantity<1||!['reserved','consumed','refunded'].includes(a.phase)||!Array.isArray(a.parts)||new Set(a.parts.map(p=>p.stockpileId)).size!==a.parts.length||!a.parts.every(p=>s.stockpilesById[p.stockpileId]&&Number.isSafeInteger(p.quantity)&&p.quantity>0)||a.parts.reduce((n,p)=>n+p.quantity,0)!==a.quantity)fail('药物预约引用或数量异常。');if(a.phase==='consumed'&&!s.factsById[`fact:pill-consume:${id}`]||a.phase==='refunded'&&!s.factsById[`fact:pill-refund:${id}`])fail('药物消费或退款事实缺失。');}}for(const p of Object.values(e.patches))if(!Number.isFinite(p.remaining)||p.remaining<0||p.remaining>p.max)fail('有限资源来源异常。');for(const a of Object.values(s.activitiesById||{}))if(a.kind==='sr-harvest'&&a.reservedQuantity!==undefined&&a.reservedQuantity!==HARVEST_BATCH[a.resource])fail('采集整批预约数量异常。');for(const st of Object.values(s.stockpilesById)){if(!Number.isFinite(st.capacity)||st.capacity<0||!st.position||!Object.values(st.resources).every(v=>Number.isFinite(v)&&v>=0))fail('仓储位置、容量或数量异常：'+st.id);if(st.position.kind==='travel'&&!s.travelsById?.[st.position.travelId])fail('旅队仓储引用缺失：'+st.id);}for(const w of Object.values(s.workOrdersById))if(w.kind==='transport'){if(!s.personsById[w.carrierId]||!s.stockpilesById[w.sourceStockpileId]||!s.stockpilesById[w.targetStockpileId]||!['to-source','carrying','delivered','cancelled'].includes(w.phase)||!Object.entries(w.cargo).every(([k,v])=>legalCargoKey(k)&&v>0&&Number.isFinite(v)&&(!pillId(k)||Number.isSafeInteger(v))))fail('运输引用或状态异常。');const r=s.reservationsById[w.reservationId];if(['delivered','cancelled'].includes(w.phase)?!!r:!r||JSON.stringify(r.cost)!==JSON.stringify(w.cargo))fail('运输物资预约异常。');}for(const w of Object.values(s.workOrdersById))if(w.kind==='sr-merchant-collection'){if(!s.personsById[w.carrierId]||!s.buildingsById[w.targetId]||!s.stockpilesById[w.sourceStockpileId]||['to-source','waiting-for-goods'].includes(w.phase)&&!s.workOrdersById[w.productionWorkOrderId]||!['to-source','waiting-for-goods','carrying','delivered','cancelled','interrupted'].includes(w.phase)||!Number.isFinite(w.expectedPayment)||w.expectedPayment<0)fail('商人取货约定引用或阶段异常。');const a=s.activitiesById[w.activityId];if(['to-source','waiting-for-goods','carrying'].includes(w.phase)){if(a?.kind!=='sr-merchant-collection'||a.workOrderId!==w.id||s.personsById[w.carrierId].activityId!==a.id)fail('商人取货身体所有权异常。');}else if(a)fail('商人结束取货未清理身体活动。');if(['carrying','delivered','interrupted'].includes(w.phase)&&(!Number.isFinite(w.actualPayment)||!s.factsById[w.productionFactId]||!e.commonGoods.some(g=>g.id===`common-good:${w.targetId}:${w.productionBatch}`)))fail('已付款器物或实际付款事实缺失。');}for(const[id,o]of Object.entries(e.orders)){if(!ORDER_DEFINITIONS[id]||!['accepted','completed','declined'].includes(o.phase))fail('商单异常。');if(o.phase==='completed'&&!s.factsById[o.resultTransactionId])fail('商单结算事实缺失。');}for(const w of Object.values(s.workOrdersById))if(w.kind==='sr-crafting'){if(!RECIPES[w.recipeId]||!s.personsById[w.personId]||!s.buildingsById[w.targetId]||!['active','completed','cancelled','interrupted'].includes(w.phase)||!Number.isSafeInteger(w.durationTicks)||w.durationTicks<1||!Number.isSafeInteger(w.progressTicks)||w.progressTicks<0||w.progressTicks>w.durationTicks||!Number.isSafeInteger(w.yield)||w.yield<1||!Object.entries(w.cost).every(([k,v])=>RESOURCES[k]&&Number.isFinite(v)&&v>=0&&s.stockpilesById[w.sourceStockpileIds[k]]))fail('丹炉批次引用、成本或进度异常。');if(w.phase==='active'){const a=s.activitiesById[w.activityId],r=s.reservationsById[w.reservationId],slot=s.reservationsById[w.slotReservationId];if(a?.kind!=='sr-craft'||a.workOrderId!==w.id||s.master.activityId!==a.id||r?.kind!=='sr-craft-material'||JSON.stringify(r.cost)!==JSON.stringify(w.cost)||slot?.kind!=='sr-slot'||slot.activityId!==a.id||slot.slotId!==a.slotId)fail('丹炉材料/工位预约异常。');}else if(s.reservationsById[w.reservationId]||s.reservationsById[w.slotReservationId]||s.activitiesById[w.activityId]||w.phase==='completed'&&(!s.factsById[w.resultFactId]||w.progressTicks!==w.durationTicks))fail('已结束丹炉批次清理或产物事实异常。');}for(const a of Object.values(s.activitiesById))if(a.kind==='sr-replenish'&&(!e.patches[a.resource]||!Number.isSafeInteger(a.progressTicks)||a.progressTicks<0||a.progressTicks>=a.durationTicks||a.durationTicks!==ECONOMY_DEFINITION.replenishTicks||s.master.activityId!==a.id||s.reservationsById[a.reservationId]?.activityId!==a.id))fail('来源恢复事务异常。');return true;}
